// Obtenemos todos los datos que vienen del Error Trigger
const data = $input.first().json;

// Rescatamos el mensaje y la descripción del error (si existen)
let mensajeOriginal = data.execution?.error?.message || 'Sin mensaje';
let descOriginal = data.execution?.error?.description || 'Sin detalles';

// Función para verificar si tiene guiones bajos
function verificarFormato(texto) {
    if (texto && texto.includes('_')) {
        return "⚠️ [No se puede mostrar el mensaje original en Telegram por incompatibilidad de formato. Revisa el correo o el Sheet para leer el detalle exacto].";
    }
    return texto;
}

// Retornamos todo el objeto original, pero le sumamos dos variables "seguras"
return {
    ...data,
    mensaje_telegram: verificarFormato(mensajeOriginal),
    desc_telegram: verificarFormato(descOriginal)
};

